"""Test suite for parse_kv.py"""

import pytest
from parse_kv import parse_kv


def test_empty_input():
    assert parse_kv('') == {}


def test_simple_pairs():
    s = "key1=value1; key2=value2"
    expected = {"key1": "value1", "key2": "value2"}
    assert parse_kv(s) == expected


def test_leading_trailing_spaces():
    s = " key = value ; another = thing "
    expected = {"key": "value", "another": "thing"}
    assert parse_kv(s) == expected


def test_escaped_semicolon():
    s = "pair=value\;with;semicolon"
    expected = {"pair": "value;with;semicolon"}
    assert parse_kv(s) == expected


def test_multiple_escapes():
    s = "a=value\;b=\;c\;d"
    expected = {"a": "value; b = ; c ; d"}  # careful: need proper handling
    # Actually, better test: "a=value\\;b=\\;c\\;d"
    # Let's use a clearer example:
    s = "a=value\\;b=\\;c\\;d"
    expected = {"a": "value\\; b = \\; c \\; d"}
    assert parse_kv(s) == expected


def test_invalid_pair_skipped():
    s = "no=eq; valid=key=value"
    expected = {"key": "value"}
    assert parse_kv(s) == expected

